#pragma once

// The one way JusPrin reports an unexpected error (AGENTS.md, Error
// handling): a failure no person decided an outcome for travels up unchanged
// to the handler at the top of its entry point, and that handler, and only
// it, calls report_unexpected_error. The person is told "Something went wrong
// on our side" in ErrorReportDialog and nothing more specific; the report
// goes to JusPrin's server, which passes it to Sentry, once they press
// "Report to JusPrin team" or after they turned automatic reports on.
//
// The top handlers today: the Agent and Home pages' message handlers
// (AgentWebView, HomeWebView), the pumps that read an AI reply or title and a
// key check (AgentHost::pump_stream, AgentHost::pump_setup, reporting through
// the handler AgentWebView gives them), every place JusPrin's own code starts
// running by itself -- a CallAfter, a timer, an HTTP callback, a thread --
// through reported() below, and the pages' own top level, which sends a
// report_error message (WebShared/bridgeClient.ts). A tool call's failure goes
// to the AI model instead; one in the app's own work is also sent through
// report_if_automatic, when automatic reports are on. An exception that leaves
// any other native event is OrcaSlicer's to handle, exactly as upstream
// handles it (GUI_App::OnExceptionInMainLoop).

#include <string>
#include <utility>

namespace Slic3r::GUI::JusPrin {

// What a report holds: the lines "See what the report contains" lists, and
// all the server receives. No chat, file, project name or account.
struct ErrorReport
{
    std::string app;   // "JusPrin 2.0.0 (OrcaSlicer 2.5.0)"
    std::string os;    // "macOS 26.3"
    std::string doing; // what the app was doing, said by the top handler
    std::string error; // the error as it reached the top, unchanged
    std::string where; // the stack, where one exists (the pages' for now)
};

// The AppConfig key of "report errors automatically", off until the person
// turns it on in the dialog or in Preferences › Updates.
inline constexpr const char* kReportErrorsKey = "jusprin_report_errors_automatically";

// Reports one unexpected error: sends it at once when automatic reports are
// on, otherwise opens the dialog after the current event, over the window in
// front. Only top handlers call this.
void report_unexpected_error(std::string doing, std::string error, std::string where = {});

// Reports a tool call that failed in the app's own work, whose error already
// went to the AI model, or a start report the server answered with a fault
// (LaunchReport): sent only when automatic reports are on, and no dialog
// opens. Any thread.
void report_if_automatic(std::string doing, std::string error);

// The exception being handled, as a report names it: its type and what().
// Call inside a catch block.
std::string describe_current_exception();

// The top handler of an entry point JusPrin's own code starts: wraps the
// body of a CallAfter, a timer, an HTTP callback or a thread, so that an
// exception leaving it is reported, saying the app was `doing` this. Any
// thread.
template<class Body> auto reported(const char* doing, Body body)
{
    return [doing, body = std::move(body)](auto&&... arguments) mutable {
        try {
            body(std::forward<decltype(arguments)>(arguments)...);
        } catch (...) {
            report_unexpected_error(doing, describe_current_exception());
        }
    };
}

// The report as it would be sent now, for the dialog and the tests.
ErrorReport make_error_report(std::string doing, std::string error, std::string where);
// The JSON body the server receives (web_ent/jusprin/v2/app_errors.py).
std::string error_report_json(const ErrorReport& report);
// Posts the report to JusPrin's server, in the background.
void send_error_report(const ErrorReport& report);

} // namespace Slic3r::GUI::JusPrin
#include "ErrorReport.hpp"

#include "libslic3r/AppConfig.hpp"
#include "slic3r/GUI/GUI_App.hpp"
#include "slic3r/GUI/JusPrin/Agent/AgentConfiguration.hpp"
#include "slic3r/GUI/JusPrin/Shell/ErrorReportDialog.hpp"
#include "slic3r/GUI/JusPrin/Updates/Version.hpp"
#include "slic3r/Utils/Http.hpp"

#include <boost/core/demangle.hpp>
#include <boost/log/trivial.hpp>
#include <nlohmann/json.hpp>

#include <wx/thread.h>
#include <wx/utils.h>
#include <wx/window.h>

#include <algorithm>
#include <deque>
#include <filesystem>
#include <typeinfo>
#include <utility>
#include <vector>

namespace Slic3r::GUI::JusPrin {

namespace {

std::string os_label()
{
    int major = 0, minor = 0, micro = 0;
    wxGetOsVersion(&major, &minor, &micro);
#if defined(__APPLE__)
    const std::string name = "macOS";
#elif defined(_WIN32)
    const std::string name = "Windows";
#else
    const std::string name = "Linux";
#endif
    return name + " " + std::to_string(major) + "." + std::to_string(minor) + (micro > 0 ? "." + std::to_string(micro) : "");
}

bool reports_automatically()
{
    return wxGetApp().app_config != nullptr && wxGetApp().app_config->get_bool(kReportErrorsKey);
}

// The reports waiting for the person, one dialog at a time. A failure that
// repeats while its dialog is open or waiting adds nothing: the person has one
// thing to answer. Nor does one they already answered in this run: a failure
// that comes back each time a window is in front again would otherwise reopen
// the dialog as soon as it closes, since closing it puts the window in front.
std::deque<ErrorReport>  g_waiting;
std::vector<ErrorReport> g_answered;
bool                     g_showing = false;

bool same_failure(const ErrorReport& a, const ErrorReport& b) { return a.doing == b.doing && a.error == b.error; }

void show_next()
{
    if (g_showing || g_waiting.empty())
        return;
    g_showing = true;
    const ErrorReport report = g_waiting.front();
    const ErrorReportDialog::Answer answer = ErrorReportDialog::ask(report);
    g_waiting.pop_front();
    g_answered.push_back(report);
    g_showing = false;
    if (answer.automatically) {
        wxGetApp().app_config->set_bool(kReportErrorsKey, true);
        wxGetApp().app_config->save();
    }
    if (answer.report)
        send_error_report(report);
    // Once reports go automatically, the ones still waiting go too.
    if (answer.automatically) {
        for (const ErrorReport& waiting : g_waiting)
            send_error_report(waiting);
        g_waiting.clear();
    }
    if (!g_waiting.empty())
        wxGetApp().CallAfter([] { show_next(); });
}

} // namespace

ErrorReport make_error_report(std::string doing, std::string error, std::string where)
{
    // A path in the error names the person's home folder, which names them;
    // the report says "~" instead.
    const std::string home = wxGetHomeDir().ToUTF8().data();
    const auto without_home = [&home](std::string text) {
        if (home.size() > 1)
            for (std::size_t at = text.find(home); at != std::string::npos; at = text.find(home, at + 1))
                text.replace(at, home.size(), "~");
        return text;
    };
    // The server refuses a field over its limit (web_ent/jusprin/v2/app_errors.py
    // FIELDS), counted in characters; cutting at as many bytes, on a
    // character boundary, keeps every field within it.
    const auto within = [](std::string text, std::size_t limit) {
        if (text.size() > limit) {
            std::size_t end = limit;
            while (end > 0 && (static_cast<unsigned char>(text[end]) & 0xC0) == 0x80)
                --end;
            text.resize(end);
        }
        return text;
    };
    return ErrorReport{Updates::version_label(), os_label(), within(std::move(doing), 500), within(without_home(std::move(error)), 8000),
                       within(without_home(std::move(where)), 32000)};
}

std::string error_report_json(const ErrorReport& report)
{
    return nlohmann::json{{"app", report.app}, {"os", report.os}, {"doing", report.doing}, {"error", report.error}, {"where", report.where}}
        .dump();
}

void send_error_report(const ErrorReport& report)
{
    const std::string url = Agent::cloud_error_reports_url(wxGetApp().app_config);
    // Anonymous: no token or cookie goes with it.
    Slic3r::Http::post(url)
        .header("User-Agent", Updates::user_agent())
        .header("Content-Type", "application/json")
        .header("Accept", "application/json")
        .set_post_body(error_report_json(report))
        .tls_verify(true)
        .timeout_connect(10)
        .timeout_max(30)
        // A report that cannot be sent has nowhere to be reported to.
        .on_error([url](std::string body, std::string error, unsigned status) {
            BOOST_LOG_TRIVIAL(error) << "JusPrin could not send an error report to " << url << " (" << status << "): " << error << " " << body;
        })
        .perform();
}

void report_unexpected_error(std::string doing, std::string error, std::string where)
{
    // An entry point on another thread (an HTTP callback, a worker) reports
    // on the main thread, where the waiting reports and the dialog live.
    if (!wxThread::IsMain()) {
        wxGetApp().CallAfter([doing = std::move(doing), error = std::move(error), where = std::move(where)]() mutable {
            report_unexpected_error(std::move(doing), std::move(error), std::move(where));
        });
        return;
    }
    ErrorReport report = make_error_report(std::move(doing), std::move(error), std::move(where));
    BOOST_LOG_TRIVIAL(error) << "Unexpected error while " << report.doing << ": " << report.error;
    if (reports_automatically()) {
        send_error_report(report);
        return;
    }
    const auto same = [&report](const ErrorReport& asked) { return same_failure(asked, report); };
    if (std::any_of(g_waiting.begin(), g_waiting.end(), same) || std::any_of(g_answered.begin(), g_answered.end(), same))
        return;
    g_waiting.push_back(std::move(report));
    // After the event that failed: the dialog's own loop never runs inside a
    // page's message handler or the main loop's exception hook.
    wxGetApp().CallAfter([] { show_next(); });
}

void report_if_automatic(std::string doing, std::string error)
{
    // From another thread (an HTTP callback), on the main thread, where the
    // settings it reads are written.
    if (!wxThread::IsMain()) {
        wxGetApp().CallAfter([doing = std::move(doing), error = std::move(error)]() mutable {
            report_if_automatic(std::move(doing), std::move(error));
        });
        return;
    }
    if (reports_automatically())
        send_error_report(make_error_report(std::move(doing), std::move(error), {}));
}

std::string describe_current_exception()
{
    try {
        throw;
    } catch (const std::filesystem::filesystem_error& error) {
        // Its paths name the person's files and projects, which a report
        // never holds: each becomes "<path>". Where a path is not found as
        // written (another encoding), only the error's code is kept.
        std::string text = error.what();
        for (const std::filesystem::path* path : {&error.path1(), &error.path2()}) {
            const std::string named = path->u8string();
            if (named.empty())
                continue;
            if (text.find(named) == std::string::npos) {
                text = error.code().message();
                break;
            }
            for (std::size_t at = text.find(named); at != std::string::npos; at = text.find(named, at + 6))
                text.replace(at, named.size(), "<path>");
        }
        return boost::core::demangle(typeid(error).name()) + ": " + text;
    } catch (const std::exception& error) {
        return boost::core::demangle(typeid(error).name()) + ": " + error.what();
    } catch (...) {
        return "an exception that is not a std::exception";
    }
}

} // namespace Slic3r::GUI::JusPrin
